/* ===== 1.0.10 (M-22c) — una voce per ogni compagno =====
   Prima i 7 compagni dicevano le stesse frasi (cambiava solo il motto). Ora ognuno ha le sue: 5 frasi quando completi un
   obiettivo, 3 promemoria (che entrano nella rotazione al posto di 3 frasi generiche, mai al posto delle frasi di sola
   compagnia usate dopo un momento difficile) e 2 risposte di ascolto in chat (solo al posto della risposta generica,
   mai nelle risposte di aiuto). Testi in 14 lingue. */
const V110_VOICE = {"germo": {"cheer": {"it": ["Fatto. Sento una fogliolina nuova spuntare.", "Piano piano, ecco un altro germoglio.", "Questo passo mi fa fiorire un pochino.", "Che bella luce oggi, grazie a te.", "Si cresce così: un gesto alla volta."], "en": ["Done. I can feel a new little leaf.", "Slowly, slowly, another sprout.", "That step makes me bloom a little.", "Such lovely light today, thanks to you.", "This is how we grow: one small thing at a time."], "de": ["Geschafft. Ich spüre ein neues Blättchen.", "Ganz langsam wächst ein neuer Trieb.", "Dieser Schritt lässt mich ein bisschen blühen.", "So schönes Licht heute, dank dir.", "So wachsen wir: eins nach dem anderen."], "es": ["Hecho. Siento brotar una hojita nueva.", "Poquito a poco, otro brote más.", "Este paso me hace florecer un poquito.", "Qué luz tan bonita hoy, gracias a ti.", "Así se crece: un gesto cada vez."], "fr": ["C'est fait. Je sens une nouvelle petite feuille.", "Tout doucement, encore une pousse.", "Ce pas me fait fleurir un petit peu.", "Quelle jolie lumière aujourd'hui, grâce à toi.", "C'est comme ça qu'on grandit : petit à petit."], "pt": ["Feito. Sinto uma folhinha nova brotando.", "Devagarinho, mais um broto.", "Esse passo me faz florescer um pouquinho.", "Que luz bonita hoje, graças a você.", "É assim que a gente cresce: um gesto de cada vez."], "ja": ["できたね。新しい葉っぱが出てきたよ。", "ゆっくり、またひとつ芽が出た。", "この一歩で、少し花が咲いたよ。", "今日はきれいな光。ありがとう。", "こうやって、少しずつ育つんだね。"], "ko": ["해냈어요. 새 잎이 돋는 게 느껴져요.", "천천히, 또 하나 싹이 났어요.", "이 한 걸음에 조금 꽃이 피었어요.", "오늘 빛이 참 예뻐요. 고마워요.", "이렇게 조금씩 자라는 거예요."], "zh": ["完成啦。我感觉长出了一片新叶子。", "慢慢地，又冒出一颗小芽。", "这一步让我开了一点点花。", "今天的光真好，谢谢你。", "就这样，一点一点长大。"], "zht": ["完成了。我感覺長出一片新葉子。", "慢慢地，又冒出一顆小芽。", "這一步讓我開了一點點花。", "今天的光好美，謝謝你。", "就這樣，一點一點長大。"], "ru": ["Готово. Чувствую, как растёт новый листик.", "Потихоньку, ещё один росток.", "От этого шага я чуть-чуть расцветаю.", "Сегодня такой красивый свет, спасибо тебе.", "Вот так и растём: по одному шажку."], "pl": ["Zrobione. Czuję, jak rośnie nowy listek.", "Powolutku, jeszcze jeden kiełek.", "Dzięki temu krokowi trochę rozkwitam.", "Jakie piękne dziś światło, dzięki tobie.", "Tak się rośnie: krok po kroczku."], "nl": ["Gelukt. Ik voel een nieuw blaadje groeien.", "Heel rustig komt er weer een scheutje bij.", "Door deze stap bloei ik een beetje op.", "Wat een mooi licht vandaag, dankzij jou.", "Zo groeien we: één dingetje tegelijk."], "tr": ["Tamam. Yeni bir yaprak filizleniyor sanki.", "Yavaş yavaş, bir filiz daha.", "Bu adımla biraz çiçek açıyorum.", "Bugün ışık ne güzel, senin sayende.", "İşte böyle büyürüz: azar azar."]}, "notif": {"it": ["{n} ha aperto una fogliolina nuova al sole. Se ti va, un obiettivo piccolo piccolo?", "Nel vaso di {n} è arrivato un raggio di luce. Quando vuoi, un passo leggero insieme.", "{n} cresce piano, senza fretta. Ti va di fare una cosa piccola per te, oggi?"], "en": ["{n} opened a new little leaf in the sun. Fancy a tiny goal, if you feel like it?", "A ray of light just reached {n}'s pot. Whenever you like, one gentle step together.", "{n} grows slowly, no hurry. Would you like to do one small thing for yourself today?"], "de": ["{n} hat ein neues Blättchen in die Sonne gestreckt. Wenn dir danach ist: ein winziges Ziel?", "Ein Sonnenstrahl fällt in den Topf von {n}. Wann immer du magst: ein sanfter Schritt zusammen.", "{n} wächst langsam, ganz ohne Eile. Magst du heute eine kleine Sache für dich tun?"], "es": ["{n} ha abierto una hojita nueva al sol. Si te apetece, ¿un objetivo pequeñito?", "Un rayo de luz ha llegado a la maceta de {n}. Cuando quieras, damos un pasito tranquilo.", "{n} crece despacio, sin prisa. ¿Te apetece hacer hoy algo pequeño por ti?"], "fr": ["{n} a ouvert une nouvelle petite feuille au soleil. Un tout petit objectif, si tu en as envie ?", "Un rayon de lumière touche le pot de {n}. Quand tu veux, un pas tout doux ensemble.", "{n} grandit lentement, sans se presser. Une petite chose pour toi aujourd'hui, ça te dit ?"], "pt": ["{n} abriu uma folhinha nova no sol. Se você quiser, que tal uma meta pequenininha?", "Um raio de luz chegou no vasinho de {n}. Quando quiser, a gente dá um passinho leve.", "{n} cresce devagar, sem pressa. Que tal fazer uma coisinha por você hoje?"], "ja": ["{n}が日なたで新しい葉っぱをひらいたよ。よかったら小さな目標をひとつ、どう？", "{n}の鉢にやさしい光が届いたよ。気が向いたら、いっしょに一歩だけ。", "{n}はゆっくり、のんびり育ってるよ。今日、自分のために小さなことをしてみる？"], "ko": ["{n}의 새 잎이 햇살 아래 펼쳐졌어요. 괜찮다면 작은 목표 하나, 어때요?", "{n}의 화분에 따스한 빛이 들어요. 원할 때 함께 한 걸음만 가 봐요.", "{n}의 싹은 서두르지 않고 천천히 자라요. 오늘 너를 위한 작은 일 하나, 해 볼래요?"], "zh": ["{n} 在阳光下展开了一片新叶子。想的话，来一个小小的目标吧？", "一缕阳光照进了 {n} 的花盆。你愿意的时候，我们一起迈一小步。", "{n} 慢慢地长，不着急。今天想为自己做一件小事吗？"], "zht": ["{n} 在陽光下展開了一片新葉子。想的話，來一個小小的目標吧？", "一道陽光照進了 {n} 的花盆。你想的時候，我們一起跨出一小步。", "{n} 慢慢地長，不用急。今天想為自己做一件小事嗎？"], "ru": ["{n} раскрывает на солнце новый листик. Если хочется, может, одну маленькую цель?", "Лучик света заглядывает в горшок, где растёт {n}. Когда захочешь, сделаем один мягкий шаг.", "{n} растёт медленно, без спешки. Хочешь сегодня сделать что-то маленькое для себя?"], "pl": ["{n} rozwija w słońcu nowy listek. Jeśli masz ochotę, może jeden malutki cel?", "Promyk światła zagląda do doniczki, gdzie rośnie {n}. Kiedy zechcesz, jeden spokojny krok razem?", "{n} rośnie powoli, bez pośpiechu. Masz ochotę zrobić dziś coś małego dla siebie?"], "nl": ["{n} heeft een nieuw blaadje in de zon geopend. Zin in een piepklein doel, als je wilt?", "Er valt een zonnestraal in het potje van {n}. Wanneer je wilt: samen één zachte stap.", "{n} groeit langzaam, zonder haast. Zin om vandaag iets kleins voor jezelf te doen?"], "tr": ["{n} güneşte yeni bir yaprak açtı. İstersen küçücük bir hedefe ne dersin?", "Bir güneş ışını şimdi {n} ile buluştu. Ne zaman istersen, birlikte yumuşak bir adım atalım.", "{n} acele etmeden, yavaş yavaş büyüyor. Bugün kendin için küçük bir şey yapmak ister misin?"]}, "chat": {"it": ["Forse non ho capito bene. Me lo racconti con calma? Io resto qui ad ascoltarti.", "Prendiamoci tutto il tempo che serve. Dimmi pure di più, ti ascolto con attenzione."], "en": ["I'm not sure I understood. Could you tell me a bit more, gently? I'm right here, listening.", "Let's take all the time we need. Tell me more if you'd like. I'm listening."], "de": ["Vielleicht hab ich das nicht ganz verstanden. Erzählst du mir in Ruhe mehr? Ich bin da und hör dir zu.", "Wir lassen uns alle Zeit, die wir brauchen. Erzähl mir gern mehr, ich hör dir zu."], "es": ["Puede que no lo haya entendido bien. ¿Me lo cuentas con calma? Aquí estoy, escuchándote.", "Tomémonos todo el tiempo que haga falta. Cuéntame más si quieres, te escucho."], "fr": ["Je n'ai peut-être pas bien compris. Tu me racontes tranquillement ? Je reste là, je t'écoute.", "Prenons tout le temps qu'il faut. Dis-m'en plus si tu veux, je t'écoute."], "pt": ["Acho que não entendi direito. Me conta com calma? Estou aqui, ouvindo você.", "Vamos com todo o tempo que precisar. Me conta mais, se quiser. Estou ouvindo."], "ja": ["うまくわからなかったかも。ゆっくりでいいから、もう少し聞かせてくれる？ここで聞いてるよ。", "時間はたっぷりあるよ。話したいことがあれば、なんでも聞かせてね。"], "ko": ["내가 잘 못 알아들었나 봐요. 천천히 조금 더 이야기해 줄래요? 여기서 듣고 있어요.", "시간은 얼마든지 있어요. 하고 싶은 이야기가 있으면 들려줘요. 귀 기울이고 있어요."], "zh": ["我可能没太听懂。你可以慢慢再跟我说说吗？我就在这里听着。", "我们有很多时间，不用急。想说什么都可以告诉我，我在听。"], "zht": ["我可能沒有完全聽懂。可以慢慢再跟我說說嗎？我就在這裡聽。", "我們有很多時間，不用急。想說什麼都可以告訴我，我在聽。"], "ru": ["Кажется, я не до конца понимаю. Расскажешь спокойно, подробнее? Я здесь и слушаю.", "Давай не будем спешить. Расскажи больше, если хочется. Я внимательно слушаю."], "pl": ["Chyba nie do końca rozumiem. Opowiesz mi spokojnie coś więcej? Jestem tutaj i słucham.", "Mamy tyle czasu, ile trzeba. Opowiedz więcej, jeśli chcesz. Słucham cię uważnie."], "nl": ["Misschien begrijp ik het niet helemaal. Vertel je er rustig wat meer over? Ik ben hier en luister.", "We nemen alle tijd die nodig is. Vertel gerust meer, ik luister naar je."], "tr": ["Galiba tam anlayamadım. Bana sakin sakin biraz daha anlatır mısın? Buradayım, seni dinliyorum.", "Acele yok, ne kadar zaman gerekirse. İstersen daha fazlasını anlat, seni dinliyorum."]}}, "ondi": {"cheer": {"it": ["Splash! Un sassolino in più nella mia collezione.", "Evviva! Faccio una capriola nell'acqua.", "Fatto! Un bel respiro lento, che bello.", "Questo sassolino lo tengo per te.", "Che bello! Galleggio felice sull'acqua."], "en": ["Splash! One more pebble for my collection.", "Hooray! I'm doing a little flip in the water.", "Done! A nice slow breath. Lovely.", "I'm keeping this pebble just for you.", "Yay! I'm floating along, so happy."], "de": ["Platsch! Noch ein Kiesel für meine Sammlung.", "Hurra! Ich mach einen Purzelbaum im Wasser.", "Geschafft! Ein schöner, langsamer Atemzug.", "Diesen Kiesel heb ich für dich auf.", "Juhu! Ich treib ganz glücklich auf dem Wasser."], "es": ["¡Chof! Una piedrecita más para mi colección.", "¡Bien! Doy una voltereta en el agua.", "¡Hecho! Una respiración lenta, qué gusto.", "Esta piedrecita la guardo para ti.", "¡Qué bien! Floto feliz en el agua."], "fr": ["Plouf ! Un galet de plus pour ma collection.", "Youpi ! Je fais une galipette dans l'eau.", "C'est fait ! Une lente respiration, que c'est doux.", "Ce petit galet, je le garde pour toi.", "Trop bien ! Je me laisse flotter dans l'eau."], "pt": ["Tchibum! Mais uma pedrinha para a minha coleção.", "Eba! Vou dar uma cambalhota na água.", "Feito! Uma respiração lenta, que bom.", "Essa pedrinha eu guardo para você.", "Que legal! Estou boiando feliz na água."], "ja": ["ぽちゃん！石ころコレクションが増えたよ。", "やったね！水の中でくるんと一回転。", "できた！ゆっくり深呼吸、気持ちいい。", "この小石、あなたのためにとっておくね。", "わーい！ぷかぷか浮かんでごきげん。"], "ko": ["첨벙! 내 조약돌 모음에 하나가 더 생겼어요.", "야호! 물속에서 한 바퀴 빙글 돌았어요.", "해냈어요! 천천히 숨 한 번, 기분 좋아요.", "이 조약돌은 너를 위해 간직할게요.", "좋아요! 물 위에 둥둥 떠서 신나요."], "zh": ["扑通！我的石头收藏又多了一颗。", "耶！我在水里翻了个跟头。", "完成！慢慢吸一口气，好舒服。", "这颗小石头，我留给你。", "真好！我在水上开心地漂呀漂。"], "zht": ["噗通！我的石頭收藏又多了一顆。", "耶！我在水裡翻了個跟斗。", "完成！慢慢吸一口氣，好舒服。", "這顆小石頭，我留給你。", "真好！我在水上開心地漂呀漂。"], "ru": ["Плюх! Ещё один камешек в мою коллекцию.", "Ура! Кувыркаюсь в воде.", "Готово! Медленный вдох, как приятно.", "Этот камешек я сберегу для тебя.", "Здорово! Покачиваюсь на воде от радости."], "pl": ["Plusk! Jeszcze jeden kamyczek do mojej kolekcji.", "Hura! Robię fikołka w wodzie.", "Zrobione! Powolny oddech, jak przyjemnie.", "Ten kamyczek zachowam dla ciebie.", "Super! Unoszę się na wodzie z radości."], "nl": ["Plons! Weer een steentje voor mijn verzameling.", "Hoera! Ik maak een koprol in het water.", "Gelukt! Eén rustige ademhaling, heerlijk.", "Dit steentje bewaar ik voor jou.", "Leuk! Ik dobber blij in het water."], "tr": ["Şap! Koleksiyonuma bir çakıl taşı daha.", "Yaşasın! Suda bir takla atıyorum.", "Tamam! Yavaş bir nefes, ne hoş.", "Bu çakıl taşını senin için saklıyorum.", "Harika! Suyun üstünde mutlu mutlu yüzüyorum."]}, "notif": {"it": ["{n} sta facendo saltare un sassolino sull'acqua. Se ti va, un obiettivo piccolo?", "{n} galleggia piano e fa un respiro lento. Ti va di farne uno anche tu, e poi un passo piccolo?", "{n} ha messo in fila i sassolini più belli. Quando vuoi, ne aggiungiamo uno insieme."], "en": ["{n} is skipping a pebble across the water. One small goal, if you feel like it?", "{n} is floating slowly, taking a long, easy breath. Want to join in, then try one small step?", "{n} lined up the shiniest pebbles. Whenever you like, we can add one together."], "de": ["{n} lässt einen Kiesel übers Wasser hüpfen. Ein kleines Ziel, wenn dir danach ist?", "{n} treibt ganz langsam und atmet tief und ruhig. Magst du mitmachen und dann einen kleinen Schritt?", "{n} hat die glänzendsten Kiesel aufgereiht. Wann immer du magst, legen wir zusammen einen dazu."], "es": ["{n} está haciendo saltar una piedrecita en el agua. Si te apetece, ¿un objetivo pequeño?", "{n} flota despacito y respira hondo y tranquilo. ¿Te animas tú también, y luego un pasito?", "{n} ha puesto en fila sus piedrecitas más brillantes. Cuando quieras, añadimos una más."], "fr": ["{n} fait des ricochets avec un petit galet. Un petit objectif, si tu en as envie ?", "{n} flotte tout doucement et respire lentement. Tu veux essayer aussi, puis faire un petit pas ?", "{n} a aligné ses galets les plus brillants. Quand tu veux, on en ajoute un ensemble."], "pt": ["{n} está quicando uma pedrinha na água. Se você quiser, que tal uma meta pequena?", "{n} está boiando devagar e respirando bem fundo. Quer tentar também, e depois um passinho?", "{n} colocou em fila as pedrinhas mais brilhantes. Quando quiser, a gente põe mais uma."], "ja": ["{n}が水の上で小石をはねさせてるよ。よかったら小さな目標をひとつ、どう？", "{n}がぷかぷか浮かんで、ゆっくり息をしてるよ。いっしょにどう？そのあと一歩だけ。", "{n}がぴかぴかの小石を並べたよ。気が向いたら、いっしょにもうひとつ足そう。"], "ko": ["{n}의 조약돌이 물 위를 통통 튀어요. 괜찮다면 작은 목표 하나, 어때요?", "물 위에 둥둥, {n}의 숨이 느긋해요. 같이 숨 한 번 쉬고 작은 한 걸음, 어때요?", "반짝이는 조약돌이 {n}의 곁에 나란히 있어요. 원할 때 같이 하나 더 놓아요."], "zh": ["{n} 正在水面上打水漂。想的话，来一个小目标吧？", "{n} 在水上慢慢漂着，轻轻地呼吸。要不要一起试试，再走一小步？", "{n} 把最亮的小石头排成了一排。你愿意的时候，我们再添一颗。"], "zht": ["{n} 正在水面上打水漂。想的話，來一個小目標吧？", "{n} 在水上慢慢漂著，輕輕地呼吸。要不要一起試試，再跨出一小步？", "{n} 把最亮的小石頭排成一排。你想的時候，我們再放一顆上去。"], "ru": ["{n} пускает камешек прыгать по воде. Если хочется, может, одну маленькую цель?", "{n} медленно покачивается на воде и спокойно дышит. Попробуешь тоже, а потом маленький шаг?", "{n} выкладывает в ряд самые блестящие камешки. Когда захочешь, добавим ещё один вместе."], "pl": ["{n} puszcza kaczki kamyczkiem po wodzie. Jeśli masz ochotę, może jeden mały cel?", "{n} powoli unosi się na wodzie i spokojnie oddycha. Spróbujesz też, a potem jeden mały krok?", "{n} układa w rządku najładniejsze kamyczki. Kiedy zechcesz, dołożymy razem jeszcze jeden."], "nl": ["{n} laat een steentje over het water ketsen. Zin in een klein doel, als je wilt?", "{n} dobbert langzaam rond en ademt rustig. Doe je even mee, en daarna één klein stapje?", "{n} heeft de mooiste steentjes op een rij gelegd. Wanneer je wilt, leggen we er samen eentje bij."], "tr": ["{n} suda taş sektiriyor. İstersen küçük bir hedefe ne dersin?", "{n} suda yavaşça süzülüp sakin nefes alıyor. Sen de dener misin, sonra küçük bir adım?", "{n} en parlak çakıl taşlarını sıraya dizdi. Ne zaman istersen, birlikte bir tane daha ekleriz."]}, "chat": {"it": ["Forse non ho capito bene. Ti va di raccontarmelo con calma? Io sono qui vicino, ti ascolto.", "Come l'acqua, andiamo piano. Dimmi di più, se vuoi: ti ascolto."], "en": ["I might not have understood. Want to tell me about it slowly? I'm right here, listening.", "Like water, we can go slowly. Tell me more if you'd like. I'm listening."], "de": ["Vielleicht hab ich das nicht ganz verstanden. Magst du es mir langsam erzählen? Ich bin da und hör zu.", "Wie das Wasser, ganz langsam. Erzähl mir gern mehr, ich hör dir zu."], "es": ["Puede que no te haya entendido bien. ¿Me lo cuentas despacio? Estoy aquí cerquita, escuchándote.", "Como el agua, vamos despacio. Cuéntame más si quieres, te escucho."], "fr": ["Je n'ai peut-être pas bien compris. Tu veux me raconter doucement ? Je suis tout près, je t'écoute.", "Comme l'eau, on prend notre temps. Dis-m'en plus si tu veux, je t'écoute."], "pt": ["Acho que não entendi direito. Quer me contar com calma? Estou aqui pertinho, ouvindo você.", "Como a água, a gente vai devagar. Me conta mais, se quiser. Estou ouvindo."], "ja": ["ちゃんとわからなかったかも。ゆっくりでいいから、話してくれる？すぐそばで聞いてるよ。", "水みたいに、ゆっくりでいいよ。よかったら、もう少し聞かせてね。"], "ko": ["음, 잘 모르겠어요. 괜찮다면 천천히 들려줄래요? 바로 옆에서 듣고 있어요.", "물처럼 천천히 가도 돼요. 더 이야기하고 싶으면 들려줘요. 듣고 있어요."], "zh": ["我好像没太听懂。愿意慢慢跟我说说吗？我就在你身边听着。", "像水一样，慢慢来就好。想多说一点的话，我在听。"], "zht": ["我好像沒有完全聽懂。願意慢慢跟我說說嗎？我就在你身邊聽。", "像水一樣，慢慢來就好。想多說一點的話，我在聽。"], "ru": ["Кажется, я не совсем понимаю. Расскажешь мне не спеша? Я рядом и слушаю.", "Как вода, никуда не торопимся. Расскажи больше, если хочется. Я слушаю."], "pl": ["Chyba nie wszystko rozumiem. Opowiesz mi powoli? Jestem tuż obok i słucham.", "Jak woda, płyniemy powoli. Opowiedz więcej, jeśli chcesz. Słucham."], "nl": ["Misschien snap ik het niet helemaal. Wil je het me rustig vertellen? Ik ben vlakbij en luister.", "Net als water: rustig aan. Vertel gerust meer, ik luister."], "tr": ["Galiba seni tam anlayamadım. Bana yavaş yavaş anlatır mısın? Hemen yanındayım, dinliyorum.", "Su gibi, yavaş yavaş gidelim. İstersen biraz daha anlat, dinliyorum."]}}, "lumi": {"cheer": {"it": ["Fatto! Si è accesa una lucina in più.", "Brillo un pochino di più, grazie a te.", "Che bello, una stellina nuova nel cielo.", "Questo passo illumina la serata.", "Ogni passo è una piccola luce."], "en": ["Done! One more little light just came on.", "I'm glowing a bit brighter, thanks to you.", "How lovely, a new little star in the sky.", "That step lights up the whole evening.", "Every step is a tiny light."], "de": ["Geschafft! Ein Lichtlein mehr leuchtet.", "Ich leuchte ein bisschen heller, dank dir.", "Wie schön, ein neues Sternchen am Himmel.", "Dieser Schritt macht den Abend hell.", "Jeder Schritt ist ein kleines Licht."], "es": ["¡Hecho! Se ha encendido una lucecita más.", "Brillo un poquito más, gracias a ti.", "Qué bonito, una estrellita nueva en el cielo.", "Este paso ilumina toda la noche.", "Cada paso es una pequeña luz."], "fr": ["C'est fait ! Une petite lumière de plus s'allume.", "Je brille un peu plus fort, grâce à toi.", "Que c'est joli, une nouvelle petite étoile.", "Ce pas illumine toute la soirée.", "Chaque pas est une petite lumière."], "pt": ["Feito! Mais uma luzinha acendeu.", "Estou brilhando um pouco mais, graças a você.", "Que lindo, uma estrelinha nova no céu.", "Esse passo ilumina a noite toda.", "Cada passo é uma luzinha."], "ja": ["できた！小さな明かりがまたひとつ。", "ありがとう、少し明るく光れたよ。", "わあ、空に新しいお星さま。", "この一歩で、夜がぽっと明るくなった。", "一歩ずつが、小さな光になるね。"], "ko": ["해냈어요! 작은 불빛이 하나 더 켜졌어요.", "덕분에 조금 더 밝게 빛나요.", "와, 하늘에 새 별이 떴어요.", "이 한 걸음이 밤을 환하게 밝혀요.", "한 걸음 한 걸음이 작은 빛이에요."], "zh": ["完成！又亮起了一盏小灯。", "谢谢你，我又亮了一点点。", "真美，天上多了一颗小星星。", "这一步把整个夜晚都照亮了。", "每一步都是一点小小的光。"], "zht": ["完成！又亮起了一盞小燈。", "謝謝你，我又亮了一點點。", "好美，天上多了一顆小星星。", "這一步把整個夜晚都照亮了。", "每一步都是一點小小的光。"], "ru": ["Готово! Зажёгся ещё один огонёк.", "Свечусь чуть ярче, спасибо тебе.", "Как красиво, на небе новая звёздочка.", "Этот шаг освещает весь вечер.", "Каждый шаг как маленький огонёк."], "pl": ["Zrobione! Zapala się kolejne światełko.", "Świecę trochę jaśniej, dzięki tobie.", "Jak pięknie, nowa gwiazdka na niebie.", "Ten krok rozświetla cały wieczór.", "Każdy krok to małe światełko."], "nl": ["Gelukt! Er gaat weer een lichtje aan.", "Ik straal een beetje feller, dankzij jou.", "Wat mooi, een nieuw sterretje aan de hemel.", "Deze stap maakt de hele avond licht.", "Elke stap is een klein lichtje."], "tr": ["Tamam! Bir ışık daha yandı.", "Senin sayende biraz daha parlıyorum.", "Ne güzel, gökyüzünde yeni bir yıldız.", "Bu adım bütün akşamı aydınlatıyor.", "Her adım küçük bir ışık."]}, "notif": {"it": ["{n} ha acceso una lucina vicino alla finestra. Se ti va, un obiettivo piccolo e tranquillo?", "Spuntano le prime stelle e {n} brilla piano. Quando vuoi, una cosa piccola per te.", "{n} ha contato tre stelline nuove. Ti va di aggiungerne una con un piccolo passo?"], "en": ["{n} lit a little light by the window. A small, calm goal, if you feel like it?", "The first stars are out and {n} is glowing softly. Whenever you like, one small thing for you.", "{n} counted three new little stars. Want to add one more with a small step?"], "de": ["{n} hat am Fenster ein Lichtlein angezündet. Ein kleines, ruhiges Ziel, wenn dir danach ist?", "Die ersten Sterne gehen auf und {n} leuchtet sanft. Wann immer du magst: eine Kleinigkeit für dich.", "{n} hat drei neue Sternchen gezählt. Magst du mit einem kleinen Schritt eins dazutun?"], "es": ["{n} ha encendido una lucecita junto a la ventana. Si te apetece, ¿un objetivo pequeño y tranquilo?", "Salen las primeras estrellas y {n} brilla suave. Cuando quieras, algo pequeño para ti.", "{n} ha contado tres estrellitas nuevas. ¿Añadimos una más con un pasito?"], "fr": ["{n} a allumé une lumière près de la fenêtre. Un petit objectif tout calme, si tu veux ?", "Les premières étoiles s'allument et {n} brille doucement. Quand tu veux, une petite chose pour toi.", "{n} a compté trois nouvelles petites étoiles. On en ajoute une avec un petit pas ?"], "pt": ["{n} acendeu uma luzinha perto da janela. Se quiser, que tal uma meta pequena e tranquila?", "As primeiras estrelas apareceram e {n} brilha de leve. Quando quiser, uma coisinha por você.", "{n} contou três estrelinhas novas. Quer acrescentar mais uma com um passinho?"], "ja": ["{n}が窓のそばに小さな明かりをともしたよ。よかったら、静かな目標をひとつどう？", "一番星が出てきて、{n}がやさしく光ってるよ。気が向いたら、自分のために小さなことを。", "{n}が新しいお星さまを3つ数えたよ。小さな一歩で、もうひとつ増やしてみる？"], "ko": ["창가에 {n}의 작은 불빛이 켜졌어요. 괜찮다면 조용한 목표 하나, 어때요?", "첫 별이 뜨고 {n}의 불빛이 은은해요. 원할 때 너를 위한 작은 일 하나 해 봐요.", "{n}의 하늘에 새 별이 셋 생겼어요. 작은 한 걸음으로 하나 더 늘려 볼래요?"], "zh": ["{n} 在窗边点亮了一盏小灯。想的话，来一个安静的小目标吧？", "第一颗星星出来了，{n} 轻轻地亮着。你想的时候，为自己做一件小事吧。", "{n} 数到了三颗新的小星星。要不要用一小步再添一颗？"], "zht": ["{n} 在窗邊點亮了一盞小燈。想的話，來一個安靜的小目標吧？", "第一顆星星出來了，{n} 輕輕地亮著。你想的時候，為自己做一件小事吧。", "{n} 數到了三顆新的小星星。要不要用一小步再多一顆？"], "ru": ["{n} зажигает огонёк у окна. Если хочется, может, одну маленькую спокойную цель?", "Зажигаются первые звёзды, и {n} тихонько светится. Когда захочешь, что-то маленькое для себя.", "{n} считает новые звёздочки: уже три! Добавим ещё одну маленьким шагом?"], "pl": ["{n} zapala światełko przy oknie. Jeśli masz ochotę, może jeden mały, spokojny cel?", "Wychodzą pierwsze gwiazdy, a {n} świeci delikatnie. Kiedy zechcesz, coś małego dla siebie.", "{n} liczy nowe gwiazdki: już trzy! Dodamy jeszcze jedną małym krokiem?"], "nl": ["{n} heeft een lichtje bij het raam aangedaan. Zin in een klein, rustig doel, als je wilt?", "De eerste sterren komen op en {n} straalt zachtjes. Wanneer je wilt: iets kleins voor jezelf.", "{n} heeft drie nieuwe sterretjes geteld. Zullen we er met een klein stapje eentje bij doen?"], "tr": ["{n} pencerenin yanında küçük bir ışık yaktı. İstersen sakin, küçük bir hedefe ne dersin?", "İlk yıldızlar çıkıyor ve {n} yumuşacık parlıyor. Ne zaman istersen, kendin için küçük bir şey.", "{n} üç yeni yıldız saydı. Küçük bir adımla bir tane daha ekleyelim mi?"]}, "chat": {"it": ["Forse non ho capito bene. Raccontami pure, con calma: ti faccio un po' di luce e ascolto.", "Sono qui accanto a te, con la mia lucina. Dimmi di più, se ti va. Ti ascolto."], "en": ["I might not have understood. Tell me gently, if you like. I'll glow softly here and listen.", "I'm right here beside you, with my little light. Tell me more if you'd like. I'm listening."], "de": ["Vielleicht hab ich das nicht ganz verstanden. Erzähl mir gern in Ruhe. Ich leuchte sanft und hör zu.", "Ich bin hier bei dir, mit meinem kleinen Licht. Erzähl mir mehr, wenn du magst. Ich hör zu."], "es": ["Puede que no lo haya entendido bien. Cuéntamelo con calma, si quieres. Brillo suave aquí y te escucho.", "Estoy aquí a tu lado, con mi lucecita. Cuéntame más si te apetece. Te escucho."], "fr": ["Je n'ai peut-être pas bien compris. Raconte-moi doucement, si tu veux. Je brille tout doux et j'écoute.", "Je suis là, à côté de toi, avec ma petite lumière. Dis-m'en plus si tu veux. Je t'écoute."], "pt": ["Acho que não entendi direito. Me conta com calma, se quiser. Fico aqui brilhando de leve e ouvindo.", "Estou aqui do seu lado, com a minha luzinha. Me conta mais, se quiser. Estou ouvindo."], "ja": ["うまくわからなかったかも。ゆっくり話してくれる？そっと光りながら、聞いてるよ。", "小さな明かりを持って、ここにいるよ。よかったら、もう少し聞かせてね。"], "ko": ["음, 잘 모르겠어요. 천천히 이야기해 줄래요? 은은하게 빛나면서 듣고 있을게요.", "작은 불빛을 들고 네 곁에 있어요. 더 들려주고 싶으면 말해 줘요. 듣고 있어요."], "zh": ["我可能没太听懂。可以慢慢跟我说说吗？我会轻轻亮着，听你说。", "我就在你身边，带着我的小灯。想多说一点的话，我在听。"], "zht": ["我可能沒有完全聽懂。可以慢慢跟我說說嗎？我會輕輕亮著，聽你說。", "我就在你身邊，帶著我的小燈。想多說一點的話，我在聽。"], "ru": ["Кажется, я не совсем понимаю. Расскажи спокойно, если хочешь. Я тихонько свечусь рядом и слушаю.", "Я здесь, рядом с тобой, со своим огоньком. Расскажи больше, если хочется. Я слушаю."], "pl": ["Chyba nie wszystko rozumiem. Opowiedz mi spokojnie, jeśli chcesz. Świecę cichutko obok i słucham.", "Jestem tu przy tobie, z moim światełkiem. Opowiedz więcej, jeśli masz ochotę. Słucham."], "nl": ["Misschien begrijp ik het niet helemaal. Vertel het me rustig, als je wilt. Ik straal zachtjes en luister.", "Ik ben hier naast je, met mijn lichtje. Vertel gerust meer, als je wilt. Ik luister."], "tr": ["Galiba tam anlayamadım. İstersen bana sakin sakin anlat. Yanında usulca parlıyor, seni dinliyorum.", "Küçük ışığımla buradayım, yanındayım. İstersen biraz daha anlat. Dinliyorum."]}}, "miko": {"cheer": {"it": ["Fatto! Mi metto a fare le fusa.", "Che bello, mi accoccolo nel mio nido.", "Questo passo è morbido come una coperta.", "Che tepore! Grazie di cuore.", "Un passo in più, un nido più morbido."], "en": ["Done! I'm purring away.", "So nice, I'm curling up in my nest.", "That step feels soft as a blanket.", "So warm and snug! Thank you.", "One more step, one softer nest."], "de": ["Geschafft! Ich fang an zu schnurren.", "Wie schön, ich kuschel mich ins Nest.", "Dieser Schritt ist weich wie eine Decke.", "So warm und kuschelig! Danke dir.", "Ein Schritt mehr, ein weicheres Nest."], "es": ["¡Hecho! Ya estoy ronroneando.", "Qué gusto, me acurruco en mi nido.", "Este paso es suave como una manta.", "¡Qué calentito! Gracias de corazón.", "Un paso más, un nido más suave."], "fr": ["C'est fait ! Je me mets à ronronner.", "Trop doux, je me blottis dans mon nid.", "Ce pas est doux comme une couverture.", "Que c'est chaud et douillet ! Merci.", "Un pas de plus, un nid plus moelleux."], "pt": ["Feito! Já estou ronronando.", "Que gostoso, vou me aninhar no meu ninho.", "Esse passo é macio como um cobertor.", "Que quentinho! Valeu de coração.", "Mais um passo, um ninho mais macio."], "ja": ["できた！思わずのどを鳴らしちゃう。", "うれしいな、巣の中でまるくなるね。", "この一歩、毛布みたいにふんわり。", "ぽかぽかだね。ありがとう。", "一歩ふえて、巣もふかふかに。"], "ko": ["해냈어요! 기분 좋아서 그르릉거려요.", "좋아요, 둥지 속에 동그랗게 웅크려요.", "이 한 걸음, 담요처럼 폭신해요.", "따끈따끈 포근해요. 고마워요.", "한 걸음 더, 둥지가 더 폭신해져요."], "zh": ["完成！我忍不住打起了呼噜。", "真好，我在小窝里缩成一团。", "这一步像毯子一样软软的。", "暖乎乎的！谢谢你。", "多一步，小窝就更软一点。"], "zht": ["完成！我忍不住呼嚕呼嚕起來。", "真好，我在小窩裡縮成一團。", "這一步像毯子一樣軟軟的。", "暖呼呼的！謝謝你。", "多一步，小窩就更軟一點。"], "ru": ["Готово! Я уже мурлычу.", "Как хорошо, сворачиваюсь клубочком в гнёздышке.", "Этот шаг мягкий, как пледик.", "Так тепло и уютно! Спасибо тебе.", "Ещё шаг, и гнёздышко ещё мягче."], "pl": ["Zrobione! Już sobie mruczę.", "Jak miło, zwijam się w kłębek w gniazdku.", "Ten krok jest miękki jak kocyk.", "Ale cieplutko i przytulnie! Dziękuję.", "Jeszcze krok i gniazdko jest milsze."], "nl": ["Gelukt! Ik begin al te spinnen.", "Wat fijn, ik kruip lekker in mijn nestje.", "Deze stap is zacht als een dekentje.", "Zo warm en knus! Dankjewel.", "Nog een stap, een zachter nestje."], "tr": ["Tamam! Keyiften mırlıyorum.", "Ne güzel, yuvamda kıvrılıp yatıyorum.", "Bu adım battaniye gibi yumuşacık.", "Sıcacık ve rahat! Teşekkürler.", "Bir adım daha, daha yumuşak bir yuva."]}, "notif": {"it": ["{n} ha sistemato una coperta morbida nel nido. Se ti va, un obiettivo piccolo e comodo?", "{n} fa le fusa piano piano sul cuscino. Quando vuoi, una cosa piccola per te.", "{n} ha reso il nido ancora più soffice. Ti va di fare un passo piccolo, con calma?"], "en": ["{n} tucked a soft blanket into the nest. A small, cosy goal, if you feel like it?", "{n} is purring softly on the cushion. Whenever you like, one little thing for you.", "{n} made the nest even fluffier. Fancy one small step, nice and slow?"], "de": ["{n} hat eine weiche Decke ins Nest gelegt. Ein kleines, gemütliches Ziel, wenn dir danach ist?", "{n} schnurrt leise auf dem Kissen. Wann immer du magst: eine Kleinigkeit für dich.", "{n} hat das Nest noch flauschiger gemacht. Lust auf einen kleinen Schritt, ganz gemütlich?"], "es": ["{n} ha puesto una manta suave en el nido. Si te apetece, ¿un objetivo pequeño y cómodo?", "{n} ronronea bajito sobre el cojín. Cuando quieras, algo pequeño para ti.", "{n} ha dejado el nido aún más mullido. ¿Te apetece un pasito, con calma?"], "fr": ["{n} a mis une couverture toute douce dans le nid. Un petit objectif douillet, si tu en as envie ?", "{n} ronronne doucement sur le coussin. Quand tu veux, une petite chose pour toi.", "{n} a rendu le nid encore plus moelleux. Un petit pas, tranquillement, ça te dit ?"], "pt": ["{n} colocou um cobertor macio no ninho. Se quiser, que tal uma meta pequena e confortável?", "{n} está ronronando baixinho na almofada. Quando quiser, uma coisinha por você.", "{n} deixou o ninho ainda mais fofinho. Que tal um passinho, com calma?"], "ja": ["{n}が巣にやわらかい毛布をしいたよ。よかったら、ゆったりした目標をひとつどう？", "{n}がクッションの上で、そっとのどを鳴らしてるよ。気が向いたら、小さなことをひとつ。", "{n}が巣をもっとふかふかにしたよ。ゆっくり、小さな一歩はどう？"], "ko": ["{n}의 둥지에 보드라운 담요가 깔렸어요. 괜찮다면 편안한 목표 하나, 어때요?", "쿠션 위에서 {n}의 그르릉 소리가 들려요. 원할 때 작은 일 하나 해 봐요.", "{n}의 둥지가 더 폭신해졌어요. 천천히, 작은 한 걸음 어때요?"], "zh": ["{n} 在小窝里铺了一条软软的毯子。想的话，来一个舒服的小目标吧？", "{n} 在坐垫上轻轻地打着呼噜。你想的时候，为自己做一件小事吧。", "{n} 把小窝弄得更蓬松了。慢慢来，走一小步怎么样？"], "zht": ["{n} 在小窩裡鋪了一條軟軟的毯子。想的話，來一個舒服的小目標吧？", "{n} 在坐墊上輕輕地呼嚕呼嚕。你想的時候，為自己做一件小事吧。", "{n} 把小窩弄得更蓬鬆了。慢慢來，跨出一小步好嗎？"], "ru": ["{n} стелет в гнёздышке мягкий пледик. Если хочется, может, одну маленькую уютную цель?", "{n} тихонько мурлычет на подушке. Когда захочешь, что-то маленькое для себя.", "{n} взбивает гнёздышко, чтобы стало ещё мягче. Как насчёт маленького шага, не спеша?"], "pl": ["{n} rozkłada w gniazdku mięciutki kocyk. Jeśli masz ochotę, może jeden mały, przytulny cel?", "{n} cichutko mruczy na poduszce. Kiedy zechcesz, coś małego dla siebie.", "{n} moszczy gniazdko, żeby było jeszcze miększe. Może jeden mały krok, bez pośpiechu?"], "nl": ["{n} heeft een zacht dekentje in het nestje gelegd. Zin in een klein, knus doel, als je wilt?", "{n} spint zachtjes op het kussen. Wanneer je wilt: iets kleins voor jezelf.", "{n} heeft het nestje nog zachter gemaakt. Zin in één klein stapje, op je gemak?"], "tr": ["{n} yuvaya yumuşacık bir battaniye serdi. İstersen rahat, küçük bir hedefe ne dersin?", "{n} minderin üstünde usulca mırlıyor. Ne zaman istersen, kendin için küçük bir şey.", "{n} yuvayı daha da yumuşacık yaptı. Acele etmeden küçük bir adım, ne dersin?"]}, "chat": {"it": ["Forse non ho capito bene. Vieni, raccontami con calma: mi accoccolo qui vicino e ti ascolto.", "Sono qui accanto a te, come una coperta calda. Dimmi di più, se ti va. Ti ascolto."], "en": ["I might not have understood. Come, tell me slowly. I'll curl up right here and listen.", "I'm right here beside you, like a warm blanket. Tell me more if you'd like. I'm listening."], "de": ["Vielleicht hab ich das nicht ganz verstanden. Komm, erzähl's mir in Ruhe. Ich kuschel mich hin und hör zu.", "Ich bin hier bei dir, wie eine warme Decke. Erzähl mir mehr, wenn du magst. Ich hör dir zu."], "es": ["Puede que no lo haya entendido bien. Ven, cuéntamelo con calma. Me acurruco aquí y te escucho.", "Estoy aquí a tu lado, como una manta calentita. Cuéntame más si quieres. Te escucho."], "fr": ["Je n'ai peut-être pas bien compris. Viens, raconte-moi doucement. Je me blottis ici et je t'écoute.", "Je suis là, à côté de toi, comme une couverture chaude. Dis-m'en plus si tu veux. Je t'écoute."], "pt": ["Acho que não entendi direito. Vem, me conta com calma. Vou me aninhar aqui e ouvir você.", "Estou aqui do seu lado, como um cobertor quentinho. Me conta mais, se quiser. Estou ouvindo."], "ja": ["うまくわからなかったかも。こっちおいで、ゆっくり話して。そばでまるくなって聞いてるよ。", "あったかい毛布みたいに、そばにいるよ。よかったら、もう少し聞かせてね。"], "ko": ["음, 잘 모르겠어요. 이리 와서 천천히 이야기해 줄래요? 옆에 웅크리고 듣고 있을게요.", "따뜻한 담요처럼 네 곁에 있어요. 더 들려주고 싶으면 말해 줘요. 듣고 있어요."], "zh": ["我可能没太听懂。过来，慢慢跟我说吧。我就窝在你旁边听着。", "我在你身边，像一条暖暖的毯子。想多说一点的话，我在听。"], "zht": ["我可能沒有完全聽懂。過來，慢慢跟我說吧。我就窩在你旁邊聽。", "我在你身邊，像一條暖暖的毯子。想多說一點的話，我在聽。"], "ru": ["Кажется, я не совсем понимаю. Иди сюда, расскажи спокойно. Я свернусь клубочком рядом и послушаю.", "Я здесь, рядом, как тёплый пледик. Расскажи больше, если хочется. Я слушаю."], "pl": ["Chyba nie wszystko rozumiem. Chodź, opowiedz mi spokojnie. Zwinę się obok w kłębek i posłucham.", "Jestem tu przy tobie, jak ciepły kocyk. Opowiedz więcej, jeśli chcesz. Słucham."], "nl": ["Misschien begrijp ik het niet helemaal. Kom, vertel het me rustig. Ik kruip hier tegen je aan en luister.", "Ik ben hier bij je, als een warm dekentje. Vertel gerust meer, als je wilt. Ik luister."], "tr": ["Galiba tam anlayamadım. Gel, bana sakin sakin anlat. Yanına kıvrılıp seni dinliyorum.", "Sıcak bir battaniye gibi yanındayım. İstersen biraz daha anlat. Dinliyorum."]}}, "rufi": {"cheer": {"it": ["Fatto! Chissà cosa scopriamo adesso?", "Ooh, un'altra scoperta da mettere via!", "Evviva! Questo sentiero è nuovo.", "Ehi, guarda cosa abbiamo trovato!", "Un passo in più, un mistero in meno."], "en": ["Done! I wonder what we'll find next?", "Ooh, another discovery to keep!", "Hooray! This path is a new one.", "Hey, look what we found!", "One more step, one less mystery."], "de": ["Geschafft! Was wir wohl als Nächstes finden?", "Ooh, noch eine Entdeckung zum Aufheben!", "Hurra! Dieser Weg ist ganz neu.", "Hey, schau mal, was wir gefunden haben!", "Ein Schritt mehr, ein Rätsel weniger."], "es": ["¡Hecho! ¿Qué descubriremos ahora?", "¡Oh, otro descubrimiento para guardar!", "¡Bien! Este camino es nuevo.", "¡Eh, mira lo que hemos encontrado!", "Un paso más, un misterio menos."], "fr": ["C'est fait ! Qu'est-ce qu'on va découvrir ?", "Oh, encore une découverte à garder !", "Youpi ! Ce chemin est tout nouveau.", "Hé, regarde ce qu'on a trouvé !", "Un pas de plus, un mystère de moins."], "pt": ["Feito! O que será que vamos descobrir agora?", "Ooh, mais uma descoberta para guardar!", "Eba! Essa trilha é nova.", "Ei, olha o que a gente encontrou!", "Mais um passo, um mistério a menos."], "ja": ["できた！次は何が見つかるかな？", "おお、またひとつ発見だね！", "やった！この道ははじめてだ。", "ねえ、見て！こんなの見つけたよ！", "一歩進んで、なぞがひとつ解けた。"], "ko": ["해냈어요! 다음엔 뭘 발견할까요?", "오, 간직할 발견이 또 생겼어요!", "야호! 처음 가 보는 길이에요.", "저기, 우리가 뭘 찾았는지 봐요!", "한 걸음 더, 수수께끼 하나 풀렸어요."], "zh": ["完成！接下来会发现什么呢？", "哦，又一个值得收好的发现！", "耶！这条小路是新的。", "嘿，看看我们找到了什么！", "多走一步，就少一个谜。"], "zht": ["完成！接下來會發現什麼呢？", "哦，又一個值得收好的發現！", "耶！這條小路是新的。", "嘿，看看我們找到了什麼！", "多走一步，就少一個謎。"], "ru": ["Готово! Интересно, что мы найдём дальше?", "Ого, ещё одна находка на память!", "Ура! Эта тропинка совсем новая.", "Эй, смотри, что мы нашли!", "Ещё шаг, и одной загадкой меньше."], "pl": ["Zrobione! Ciekawe, co znajdziemy teraz?", "Ooo, kolejne odkrycie do schowania!", "Hura! Ta ścieżka jest zupełnie nowa.", "Hej, zobacz, co tu jest!", "Jeszcze krok, jedna zagadka mniej."], "nl": ["Gelukt! Wat zouden we nu ontdekken?", "Ooh, weer een ontdekking om te bewaren!", "Hoera! Dit pad is helemaal nieuw.", "Hé, kijk eens wat we gevonden hebben!", "Nog een stap, één raadsel minder."], "tr": ["Tamam! Acaba şimdi ne bulacağız?", "Ooo, saklanacak bir keşif daha!", "Yaşasın! Bu yol yepyeni.", "Hey, bak ne bulduk!", "Bir adım daha, bir gizem eksik."]}, "notif": {"it": ["{n} ha trovato un sentiero mai visto. Chissà dove porta? Se ti va, un obiettivo piccolo.", "{n} annusa una foglia strana. Cosa sarà? Ti va di scoprirlo con un passo piccolo?", "{n} ha in mente una piccola esplorazione. Quando vuoi, partiamo con un obiettivo piccolo."], "en": ["{n} found a path nobody's seen before. Where could it lead? One small goal, if you like.", "{n} is sniffing a curious leaf. What could it be? Want to find out with one small step?", "{n} has a little exploring trip in mind. Whenever you like, we can start with one small goal."], "de": ["{n} hat einen ganz neuen Weg entdeckt. Wohin er wohl führt? Ein kleines Ziel, wenn du magst?", "{n} schnuppert an einem komischen Blatt. Was das wohl ist? Mit einem kleinen Schritt rausfinden?", "{n} plant eine kleine Erkundungstour. Wann immer du magst, starten wir mit einem kleinen Ziel."], "es": ["{n} ha encontrado un sendero nunca visto. ¿Adónde llevará? Si te apetece, un objetivo pequeño.", "{n} olfatea una hoja curiosa. ¿Qué será? ¿Lo descubrimos con un pasito?", "{n} tiene en mente una pequeña exploración. Cuando quieras, empezamos con un objetivo pequeño."], "fr": ["{n} a trouvé un sentier jamais vu. Où peut-il mener ? Un petit objectif, si tu en as envie.", "{n} renifle une drôle de feuille. Qu'est-ce que c'est ? On le découvre avec un petit pas ?", "{n} prépare une petite exploration. Quand tu veux, on commence par un petit objectif."], "pt": ["{n} achou uma trilha que ninguém conhecia. Aonde será que vai dar? Se quiser, uma meta pequena.", "{n} está farejando uma folha curiosa. O que será? Vamos descobrir com um passinho?", "{n} está pensando numa pequena exploração. Quando quiser, a gente começa com uma meta pequena."], "ja": ["{n}が見たことのない小道を見つけたよ。どこへ続くのかな？よかったら小さな目標を。", "{n}がふしぎな葉っぱのにおいをかいでるよ。なんだろう？小さな一歩でたしかめる？", "{n}がちょっとした探検を考えてるよ。気が向いたら、小さな目標から出発しよう。"], "ko": ["{n}의 눈앞에 처음 보는 오솔길이 있어요. 어디로 이어질까요? 괜찮다면 작은 목표 하나.", "신기한 나뭇잎에 {n}의 코가 킁킁. 뭘까요? 작은 한 걸음으로 알아볼래요?", "{n}의 머릿속에 작은 탐험 계획이 있어요. 원할 때 작은 목표 하나로 출발해요."], "zh": ["{n} 发现了一条从没见过的小路。会通向哪里呢？想的话，来一个小目标吧。", "{n} 正在闻一片奇怪的叶子。那是什么呢？用一小步去看看？", "{n} 想来一次小小的探险。你愿意的时候，我们从一个小目标出发。"], "zht": ["{n} 發現了一條從沒見過的小路。會通往哪裡呢？想的話，來一個小目標吧。", "{n} 正在聞一片奇怪的葉子。那是什麼呢？用一小步去看看？", "{n} 想來一趟小小的探險。你想的時候，我們從一個小目標出發。"], "ru": ["{n} находит незнакомую тропинку. Куда же она ведёт? Если хочется, одна маленькая цель.", "{n} обнюхивает странный листик. Что же это? Узнаем с помощью маленького шага?", "{n} задумывает маленькое путешествие. Когда захочешь, начнём с одной маленькой цели."], "pl": ["{n} odkrywa nieznaną ścieżkę. Dokąd prowadzi? Jeśli masz ochotę, jeden mały cel.", "{n} obwąchuje dziwny listek. Co to może być? Sprawdzimy jednym małym krokiem?", "{n} planuje małą wyprawę. Kiedy zechcesz, zaczniemy od jednego małego celu."], "nl": ["{n} heeft een gloednieuw pad gevonden. Waar zou het heen gaan? Een klein doel, als je wilt?", "{n} snuffelt aan een gek blaadje. Wat zou het zijn? Zoeken we het uit met één klein stapje?", "{n} heeft zin in een kleine ontdekkingstocht. Wanneer je wilt, beginnen we met een klein doel."], "tr": ["{n} hiç görülmemiş bir patika buldu. Acaba nereye çıkıyor? İstersen küçük bir hedef.", "{n} tuhaf bir yaprağı kokluyor. Bu ne acaba? Küçük bir adımla öğrenelim mi?", "{n} küçük bir keşif planlıyor. Ne zaman istersen, küçük bir hedefle yola çıkarız."]}, "chat": {"it": ["Forse non ho capito bene. Mi racconti di più? Ti ascolto con le orecchie dritte, senza fretta.", "Voglio capire meglio. Raccontami pure con calma, se ti va. Sono qui e ti ascolto."], "en": ["I might not have understood. Can you tell me more? My ears are up and I'm listening, no rush.", "I'd like to understand better. Tell me about it slowly, if you like. I'm here, listening."], "de": ["Vielleicht hab ich das nicht ganz verstanden. Erzählst du mir mehr? Ich spitz die Ohren und hör zu.", "Ich möchte es gut verstehen. Erzähl mir in Ruhe davon, wenn du magst. Ich bin da und hör zu."], "es": ["Puede que no lo haya entendido bien. ¿Me cuentas más? Te escucho con las orejas atentas, sin prisa.", "Quiero entenderlo bien. Cuéntamelo con calma, si quieres. Estoy aquí, escuchándote."], "fr": ["Je n'ai peut-être pas bien compris. Tu m'en dis plus ? J'ouvre grand les oreilles, sans me presser.", "J'aimerais bien comprendre. Raconte-moi tranquillement, si tu veux. Je suis là, je t'écoute."], "pt": ["Acho que não entendi direito. Me conta mais? Estou de orelhas em pé, ouvindo, sem pressa.", "Quero entender direitinho. Me conta com calma, se quiser. Estou aqui, ouvindo você."], "ja": ["うまくわからなかったかも。もう少し教えてくれる？耳をぴんと立てて、ゆっくり聞いてるよ。", "ちゃんとわかりたいな。よかったら、ゆっくり話してね。ここで聞いてるよ。"], "ko": ["음, 잘 모르겠어요. 조금 더 알려 줄래요? 귀를 쫑긋 세우고 천천히 듣고 있어요.", "제대로 이해하고 싶어요. 괜찮다면 천천히 이야기해 줘요. 여기서 듣고 있어요."], "zh": ["我可能没太听懂。可以多跟我说一点吗？我竖着耳朵听，不着急。", "我想好好弄明白。想说的话，慢慢告诉我。我在这里听着。"], "zht": ["我可能沒有完全聽懂。可以多跟我說一點嗎？我豎起耳朵聽，不用急。", "我想好好弄懂。想說的話，慢慢告訴我。我在這裡聽。"], "ru": ["Кажется, я не совсем понимаю. Расскажешь подробнее? Ушки на макушке, я слушаю и не тороплю.", "Мне хочется хорошо понять. Расскажи спокойно, если хочется. Я здесь и слушаю."], "pl": ["Chyba nie wszystko rozumiem. Opowiesz mi więcej? Nadstawiam uszu i słucham, bez pośpiechu.", "Chcę to dobrze zrozumieć. Opowiedz spokojnie, jeśli masz ochotę. Jestem tu i słucham."], "nl": ["Misschien begrijp ik het niet helemaal. Vertel je me meer? Ik spits mijn oren en luister, zonder haast.", "Ik wil het goed begrijpen. Vertel het me rustig, als je wilt. Ik ben hier en luister."], "tr": ["Galiba tam anlayamadım. Bana biraz daha anlatır mısın? Kulaklarım dikildi, acele etmeden dinliyorum.", "Seni iyi anlamak istiyorum. İstersen sakin sakin anlat. Buradayım, dinliyorum."]}}, "pingo": {"cheer": {"it": ["Fatto! Una scivolata e via, che ridere.", "Passettino dopo passettino, ci siamo!", "Evviva! Ho fatto una piroetta sul ghiaccio.", "Un passo piccolo, ma che passo!", "Barcollo un po', ma vado avanti!"], "en": ["Done! One slide and off we go, hee hee.", "Tiny step after tiny step, we made it!", "Hooray! I did a little spin on the ice.", "A small step, but what a step!", "I wobble a bit, but I keep going!"], "de": ["Geschafft! Einmal gerutscht und weiter, hihi.", "Schrittchen für Schrittchen, wir haben's!", "Hurra! Ich hab mich auf dem Eis gedreht.", "Ein kleiner Schritt, aber was für einer!", "Ich wackel ein bisschen, aber ich geh weiter!"], "es": ["¡Hecho! Un resbalón y adelante, ji ji.", "Pasito a pasito, ¡lo logramos!", "¡Bien! He dado una vuelta sobre el hielo.", "Un paso pequeño, ¡pero qué paso!", "Me tambaleo un poco, ¡pero sigo!"], "fr": ["C'est fait ! Je glisse et c'est reparti, hi hi.", "Petit pas après petit pas, on y est !", "Youpi ! J'ai fait une pirouette sur la glace.", "Un petit pas, mais quel pas !", "Je vacille un peu, mais j'avance !"], "pt": ["Feito! Uma escorregada e lá vamos nós, hihi.", "Passinho por passinho, conseguimos!", "Eba! Dei uma piruetinha no gelo.", "Um passo pequeno, mas que passo!", "Balanço um pouco, mas sigo em frente!"], "ja": ["できた！つるっとすべって、また前へ。", "ちょこちょこ一歩ずつ、とうちゃく！", "やった！氷の上でくるっと回ったよ。", "小さな一歩、でもすごい一歩！", "ちょっとよろけても、前に進むよ！"], "ko": ["해냈어요! 미끄덩 미끄러지고 다시 출발.", "아장아장 한 걸음씩, 도착했어요!", "야호! 얼음 위에서 빙그르르 돌았어요.", "작은 한 걸음, 그래도 멋진 한 걸음!", "조금 비틀거려도 계속 가요!"], "zh": ["完成！滑一跤，接着往前走。", "一小步一小步，到啦！", "耶！我在冰上转了一个圈。", "一小步，但是好棒的一步！", "摇摇晃晃，也要继续往前！"], "zht": ["完成！滑一跤，繼續往前走。", "一小步一小步，到囉！", "耶！我在冰上轉了一個圈。", "一小步，但是好棒的一步！", "搖搖晃晃，也要繼續往前！"], "ru": ["Готово! Скольжу по льду и дальше, хи-хи.", "Шажок за шажком, и вот мы здесь!", "Ура! Кружусь на льду.", "Маленький шаг, но какой!", "Немножко шатаюсь, но иду вперёд!"], "pl": ["Zrobione! Ślizg i jedziemy dalej, hi hi.", "Kroczek po kroczku i jesteśmy!", "Hura! Kręcę piruecik na lodzie.", "Mały krok, ale jaki!", "Trochę się chwieję, ale idę dalej!"], "nl": ["Gelukt! Even glijden en door, hihi.", "Stapje voor stapje, we zijn er!", "Hoera! Ik draaide een rondje op het ijs.", "Een klein stapje, maar wat een stap!", "Ik wiebel een beetje, maar ik ga door!"], "tr": ["Tamam! Bir kayış, sonra devam, hi hi.", "Adım adım, işte geldik!", "Yaşasın! Buzun üstünde bir tur döndüm.", "Küçük bir adım, ama ne adım!", "Biraz sendeliyorum ama devam ediyorum!"]}, "notif": {"it": ["{n} ha fatto una scivolata buffa sul ghiaccio. Se ti va, un passettino anche per te?", "{n} va avanti a piccoli passi, un po' dondolando. Quando vuoi, un obiettivo piccolo insieme.", "Sul ghiaccio c'è una pista nuova e {n} la prova piano piano. Ti va di fare un passo piccolo?"], "en": ["{n} just did a funny slide on the ice. Fancy a tiny step of your own, if you like?", "{n} keeps going in small steps, wobbling a little. Whenever you like, one small goal together.", "There's a new track on the ice and {n} is trying it slowly. Want to take one small step?"], "de": ["{n} ist lustig übers Eis gerutscht. Lust auf ein kleines Schrittchen, wenn dir danach ist?", "{n} watschelt in kleinen Schritten weiter. Wann immer du magst: ein kleines Ziel zusammen.", "Auf dem Eis gibt's eine neue Bahn, und {n} probiert sie langsam aus. Magst du einen kleinen Schritt?"], "es": ["{n} ha hecho un resbalón muy gracioso en el hielo. Si te apetece, ¿un pasito para ti también?", "{n} sigue adelante a pasitos, balanceándose un poco. Cuando quieras, un objetivo pequeño.", "Hay una pista nueva en el hielo y {n} la prueba despacito. ¿Te apetece dar un pasito?"], "fr": ["{n} a glissé de façon rigolote sur la glace. Un petit pas pour toi aussi, si tu en as envie ?", "{n} avance à petits pas, en se dandinant un peu. Quand tu veux, un petit objectif ensemble.", "Il y a une nouvelle piste sur la glace et {n} l'essaie doucement. Tu veux faire un petit pas ?"], "pt": ["{n} deu uma escorregada engraçada no gelo. Se quiser, que tal um passinho seu também?", "{n} segue em frente com passinhos, balançando um pouco. Quando quiser, a gente faz uma meta pequena.", "Tem uma pista nova no gelo e {n} está testando devagar. Quer dar um passinho?"], "ja": ["{n}が氷の上でおもしろくすべったよ。よかったら、あなたも小さな一歩をどう？", "{n}がよちよち、少しずつ進んでるよ。気が向いたら、いっしょに小さな目標を。", "氷に新しいコースができて、{n}がゆっくりためしてるよ。小さな一歩、ふみだしてみる？"], "ko": ["얼음 위에서 {n}의 우스꽝스러운 미끄럼! 괜찮다면 너도 작은 한 걸음, 어때요?", "뒤뚱뒤뚱, {n}의 작은 걸음이 계속돼요. 원할 때 같이 작은 목표 하나 해요.", "얼음 위 새 길을 {n}의 발이 천천히 걸어요. 작은 한 걸음, 내디뎌 볼래요?"], "zh": ["{n} 在冰上滑了个好笑的跟头。想的话，你也来迈一小步吧？", "{n} 一摇一摆地小步向前。你想的时候，我们一起完成一个小目标。", "冰上多了一条新滑道，{n} 正慢慢试着滑。要不要迈出一小步？"], "zht": ["{n} 在冰上滑了個好笑的跤。想的話，你也來跨出一小步吧？", "{n} 一搖一擺地小步向前。你想的時候，我們一起完成一個小目標。", "冰上多了一條新滑道，{n} 正慢慢試著滑。要不要跨出一小步？"], "ru": ["{n} смешно скользит по льду. Если хочется, может, маленький шажок и для тебя?", "{n} идёт вперёд маленькими шажками, слегка покачиваясь. Когда захочешь, одна маленькая цель.", "На льду новая горка, и {n} осторожно её пробует. Сделаешь маленький шаг?"], "pl": ["{n} zabawnie ślizga się po lodzie. Jeśli masz ochotę, może mały kroczek i dla ciebie?", "{n} idzie dalej małymi kroczkami, trochę się kołysząc. Kiedy zechcesz, jeden mały cel.", "Na lodzie jest nowa ślizgawka i {n} powoli ją próbuje. Zrobisz jeden mały krok?"], "nl": ["{n} gleed net heel grappig over het ijs. Zin in een klein stapje voor jezelf, als je wilt?", "{n} waggelt in kleine stapjes verder. Wanneer je wilt: samen één klein doel.", "Er ligt een nieuwe baan op het ijs en {n} probeert hem rustig uit. Zin in één klein stapje?"], "tr": ["{n} buzda komik bir kayış yaptı. İstersen sen de küçük bir adım atmaya ne dersin?", "{n} biraz sallana sallana küçük adımlarla ilerliyor. Ne zaman istersen, birlikte küçük bir hedef.", "Buzda yeni bir pist var ve {n} onu yavaşça deniyor. Küçük bir adım atmak ister misin?"]}, "chat": {"it": ["Forse non ho capito bene. Raccontami pure, un pezzetto alla volta. Io resto qui e ti ascolto.", "Andiamo piano, passo dopo passo. Dimmi di più, se ti va. Sono qui accanto e ti ascolto."], "en": ["I might not have understood. Tell me about it, one little piece at a time. I'm right here, listening.", "We can go slowly, one step at a time. Tell me more if you'd like. I'm right beside you, listening."], "de": ["Vielleicht hab ich das nicht ganz verstanden. Erzähl mir davon, Stück für Stück. Ich bin da und hör zu.", "Wir gehen langsam, Schritt für Schritt. Erzähl mir mehr, wenn du magst. Ich bin bei dir und hör zu."], "es": ["Puede que no lo haya entendido bien. Cuéntamelo poco a poco, si quieres. Aquí estoy, escuchándote.", "Vamos despacio, paso a paso. Cuéntame más si te apetece. Estoy a tu lado, escuchándote."], "fr": ["Je n'ai peut-être pas bien compris. Raconte-moi, un petit bout à la fois. Je suis là, je t'écoute.", "On y va doucement, pas à pas. Dis-m'en plus si tu veux. Je suis à côté de toi, je t'écoute."], "pt": ["Acho que não entendi direito. Me conta aos pouquinhos, se quiser. Estou aqui, ouvindo você.", "A gente vai devagar, passo a passo. Me conta mais, se quiser. Estou do seu lado, ouvindo."], "ja": ["うまくわからなかったかも。少しずつでいいから、話してくれる？ここで聞いてるよ。", "一歩ずつ、ゆっくりでいいよ。よかったら、もう少し聞かせてね。そばにいるよ。"], "ko": ["음, 잘 모르겠어요. 조금씩 이야기해 줄래요? 여기서 듣고 있어요.", "한 걸음씩 천천히 가도 돼요. 더 들려주고 싶으면 말해 줘요. 곁에서 듣고 있어요."], "zh": ["我可能没太听懂。一点一点跟我说就好。我就在这里听着。", "我们慢慢来，一步一步。想多说一点的话，我在你身边听着。"], "zht": ["我可能沒有完全聽懂。一點一點跟我說就好。我就在這裡聽。", "我們慢慢來，一步一步。想多說一點的話，我在你身邊聽。"], "ru": ["Кажется, я не совсем понимаю. Расскажи понемножку, по кусочку. Я здесь и слушаю.", "Пойдём медленно, шаг за шагом. Расскажи больше, если хочется. Я рядом и слушаю."], "pl": ["Chyba nie wszystko rozumiem. Opowiedz mi po kawałeczku, jeśli chcesz. Jestem tu i słucham.", "Idziemy powoli, krok po kroku. Opowiedz więcej, jeśli masz ochotę. Jestem obok i słucham."], "nl": ["Misschien begrijp ik het niet helemaal. Vertel het me stukje voor stukje. Ik ben hier en luister.", "We doen het rustig, stap voor stap. Vertel gerust meer, als je wilt. Ik ben bij je en luister."], "tr": ["Galiba tam anlayamadım. Bana azar azar anlatır mısın? Buradayım, dinliyorum.", "Yavaş yavaş, adım adım gidelim. İstersen biraz daha anlat. Yanındayım, dinliyorum."]}}, "dori": {"cheer": {"it": ["Fatto! La mia fiammella scalda di più.", "Che coraggio tranquillo, il tuo.", "Questo passo mi accende un bel tepore.", "Un passo alla volta, con calma e coraggio.", "Sento il cuore caldo. Grazie."], "en": ["Done! My little flame feels warmer.", "Such quiet courage, yours.", "That step lights a cosy glow in me.", "One step at a time, calm and brave.", "My heart feels warm. Thank you."], "de": ["Geschafft! Mein Flämmchen wärmt jetzt mehr.", "Was für ein ruhiger Mut, deiner.", "Dieser Schritt macht mich innen ganz warm.", "Schritt für Schritt, ruhig und mutig.", "Mir wird warm ums Herz. Danke."], "es": ["¡Hecho! Mi llamita calienta más.", "Qué valentía tan tranquila la tuya.", "Este paso me enciende un calorcito.", "Paso a paso, con calma y valor.", "Siento el corazón calentito. Gracias."], "fr": ["C'est fait ! Ma petite flamme chauffe plus fort.", "Quel courage tranquille, le tien.", "Ce pas allume une douce chaleur en moi.", "Pas à pas, avec calme et courage.", "J'ai le cœur tout chaud. Merci."], "pt": ["Feito! Minha chaminha está esquentando mais.", "Que coragem tranquila a sua.", "Esse passo acende um calorzinho em mim.", "Passo a passo, com calma e coragem.", "Meu coração ficou quentinho. Valeu."], "ja": ["できた！小さな火がもっとあったかい。", "静かな勇気だね。すてき。", "この一歩で、心がぽかぽか。", "一歩ずつ、落ちついて、勇気をもって。", "胸のあたりがあったかいよ。ありがとう。"], "ko": ["해냈어요! 작은 불꽃이 더 따뜻해졌어요.", "조용한 용기, 정말 멋져요.", "이 한 걸음에 마음이 따끈해져요.", "한 걸음씩, 차분하게, 용기 있게.", "마음이 따뜻해요. 고마워요."], "zh": ["完成！我的小火苗更暖了。", "你的勇气，安静又温柔。", "这一步在我心里点起了暖意。", "一步一步，平静又勇敢。", "心里暖暖的。谢谢你。"], "zht": ["完成！我的小火苗更暖了。", "你的勇氣，安靜又溫柔。", "這一步在我心裡點起了暖意。", "一步一步，平靜又勇敢。", "心裡暖暖的。謝謝你。"], "ru": ["Готово! Мой огонёк греет сильнее.", "Какая у тебя тихая смелость.", "От этого шага мне так тепло внутри.", "Шаг за шагом, спокойно и смело.", "На сердце тепло. Спасибо."], "pl": ["Zrobione! Mój płomyczek grzeje mocniej.", "Jaka spokojna odwaga, ta twoja.", "Ten krok rozpala we mnie ciepełko.", "Krok po kroku, spokojnie i odważnie.", "Ciepło mi na sercu. Dziękuję."], "nl": ["Gelukt! Mijn vlammetje wordt warmer.", "Wat een rustige moed, die van jou.", "Deze stap maakt me vanbinnen warm.", "Stap voor stap, rustig en dapper.", "Mijn hart voelt warm. Dankjewel."], "tr": ["Tamam! Küçük alevim daha çok ısıtıyor.", "Senin sessiz cesaretin ne güzel.", "Bu adım içimi ısıtıyor.", "Adım adım, sakin ve cesurca.", "Kalbim sıcacık. Teşekkürler."]}, "notif": {"it": ["{n} ha acceso una fiammella calda e tranquilla. Se ti va, un obiettivo piccolo vicino al fuoco?", "{n} scalda la stanza con un soffio gentile. Quando vuoi, una cosa piccola per te.", "Basta un coraggio piccolo e calmo: {n} lo sa bene. Ti va di fare un passo piccolo oggi?"], "en": ["{n} lit a warm, calm little flame. A small goal by the fire, if you feel like it?", "{n} is warming the room with a gentle puff. Whenever you like, one small thing for you.", "It only takes a small, quiet kind of courage, and {n} knows it. Want to try one small step today?"], "de": ["{n} hat ein warmes, ruhiges Flämmchen angezündet. Ein kleines Ziel am Feuer, wenn dir danach ist?", "{n} wärmt das Zimmer mit einem sanften Hauch. Wann immer du magst: eine Kleinigkeit für dich.", "Es braucht nur ein bisschen leisen Mut, das weiß {n}. Magst du heute einen kleinen Schritt?"], "es": ["{n} ha encendido una llamita cálida. Si te apetece, ¿un objetivo pequeño junto al fuego?", "{n} calienta la habitación con un soplo suave. Cuando quieras, algo pequeño para ti.", "Basta un valor pequeño y tranquilo, y {n} lo sabe. ¿Te apetece dar un pasito hoy?"], "fr": ["{n} a allumé une petite flamme chaude et tranquille. Un petit objectif près du feu, si tu veux ?", "{n} réchauffe la pièce d'un souffle tout doux. Quand tu veux, une petite chose pour toi.", "Il suffit d'un petit courage tranquille, et {n} le sait. Un petit pas aujourd'hui, ça te dit ?"], "pt": ["{n} acendeu uma chaminha quente e tranquila. Se quiser, que tal uma meta pequena perto do fogo?", "{n} está esquentando o quarto com um soprinho suave. Quando quiser, uma coisinha por você.", "Basta uma coragem pequena e tranquila, e {n} sabe disso. Quer dar um passinho hoje?"], "ja": ["{n}があったかくて静かな火をともしたよ。よかったら、火のそばで小さな目標をひとつ。", "{n}がやさしい息で部屋をあたためてるよ。気が向いたら、自分のために小さなことを。", "小さくて静かな勇気でいいんだって、{n}は知ってるよ。今日、小さな一歩をどう？"], "ko": ["{n}의 따뜻하고 잔잔한 불꽃이 켜졌어요. 괜찮다면 불가에서 작은 목표 하나 어때요?", "{n}의 부드러운 입김에 방이 따뜻해져요. 원할 때 너를 위한 작은 일 하나 해 봐요.", "작고 조용한 용기면 충분하대요. {n}의 말이에요. 오늘 작은 한 걸음, 어때요?"], "zh": ["{n} 点起了一簇温暖安静的小火苗。想的话，在火边完成一个小目标吧？", "{n} 轻轻吹一口气，房间就暖和了。你想的时候，为自己做一件小事吧。", "只需要一点小小的、安静的勇气，{n} 知道的。今天想迈一小步吗？"], "zht": ["{n} 點起了一簇溫暖安靜的小火苗。想的話，在火邊完成一個小目標吧？", "{n} 輕輕吹一口氣，房間就暖和了。你想的時候，為自己做一件小事吧。", "只需要一點小小的、安靜的勇氣，{n} 知道的。今天想跨出一小步嗎？"], "ru": ["{n} разжигает тёплый, спокойный огонёк. Если хочется, может, одну маленькую цель у огня?", "{n} согревает комнату мягким дыханием. Когда захочешь, что-то маленькое для себя.", "Нужна совсем маленькая, тихая смелость, и {n} это знает. Сделаешь сегодня маленький шаг?"], "pl": ["{n} rozpala ciepły, spokojny płomyczek. Jeśli masz ochotę, może jeden mały cel przy ogniu?", "{n} ogrzewa pokój łagodnym chuchnięciem. Kiedy zechcesz, coś małego dla siebie.", "Wystarczy odrobina cichej odwagi, {n} dobrze o tym wie. Zrobisz dziś jeden mały krok?"], "nl": ["{n} heeft een warm, rustig vlammetje aangestoken. Een klein doel bij het vuur, als je wilt?", "{n} warmt de kamer op met een zacht zuchtje. Wanneer je wilt: iets kleins voor jezelf.", "Er is maar een beetje stille moed nodig, en {n} weet dat. Zin in één klein stapje vandaag?"], "tr": ["{n} sıcak, sakin bir alev yaktı. İstersen ateşin başında küçük bir hedefe ne dersin?", "{n} yumuşak bir nefesle odayı ısıtıyor. Ne zaman istersen, kendin için küçük bir şey.", "Küçük, sakin bir cesaret yeter; {n} bunu biliyor. Bugün küçük bir adım atmak ister misin?"]}, "chat": {"it": ["Forse non ho capito bene. Raccontami pure con calma: la mia fiammella ti tiene compagnia.", "Sono qui accanto a te, con un po' di calore. Dimmi di più, se ti va. Ti ascolto."], "en": ["I might not have understood. Tell me slowly, if you like. My little flame is keeping you company.", "I'm right here beside you, with a bit of warmth. Tell me more if you'd like. I'm listening."], "de": ["Vielleicht hab ich das nicht ganz verstanden. Erzähl mir in Ruhe. Mein Flämmchen leistet dir Gesellschaft.", "Ich bin hier bei dir, mit ein bisschen Wärme. Erzähl mir mehr, wenn du magst. Ich hör dir zu."], "es": ["Puede que no lo haya entendido bien. Cuéntamelo con calma, si quieres. Mi llamita te acompaña.", "Estoy aquí a tu lado, con un poco de calor. Cuéntame más si te apetece. Te escucho."], "fr": ["Je n'ai peut-être pas bien compris. Raconte-moi doucement, si tu veux. Ma petite flamme reste avec toi.", "Je suis là, à côté de toi, avec un peu de chaleur. Dis-m'en plus si tu veux. Je t'écoute."], "pt": ["Acho que não entendi direito. Me conta com calma, se quiser. Minha chaminha te faz companhia.", "Estou aqui do seu lado, com um pouco de calor. Me conta mais, se quiser. Estou ouvindo."], "ja": ["うまくわからなかったかも。よかったら、ゆっくり話して。小さな火がそばにいるよ。", "少しのぬくもりといっしょに、ここにいるよ。よかったら、もう少し聞かせてね。"], "ko": ["음, 잘 모르겠어요. 괜찮다면 천천히 이야기해 줘요. 작은 불꽃이 곁에 있을게요.", "따뜻한 온기를 품고 네 곁에 있어요. 더 들려주고 싶으면 말해 줘요. 듣고 있어요."], "zh": ["我可能没太听懂。想说的话，慢慢跟我说。我的小火苗陪着你。", "我就在你身边，带着一点温暖。想多说一点的话，我在听。"], "zht": ["我可能沒有完全聽懂。想說的話，慢慢跟我說。我的小火苗陪著你。", "我就在你身邊，帶著一點溫暖。想多說一點的話，我在聽。"], "ru": ["Кажется, я не совсем понимаю. Расскажи спокойно, если хочется. Мой огонёк рядом с тобой.", "Я здесь, рядом, и со мной немного тепла. Расскажи больше, если хочется. Я слушаю."], "pl": ["Chyba nie wszystko rozumiem. Opowiedz spokojnie, jeśli chcesz. Mój płomyczek jest przy tobie.", "Jestem tu przy tobie, z odrobiną ciepła. Opowiedz więcej, jeśli masz ochotę. Słucham."], "nl": ["Misschien begrijp ik het niet helemaal. Vertel het me rustig, als je wilt. Mijn vlammetje is bij je.", "Ik ben hier bij je, met een beetje warmte. Vertel gerust meer, als je wilt. Ik luister."], "tr": ["Galiba tam anlayamadım. İstersen sakin sakin anlat. Küçük alevim yanında.", "Biraz sıcaklıkla buradayım, yanındayım. İstersen biraz daha anlat. Dinliyorum."]}}};
function v110Voice(kind) { try { const v = V110_VOICE[S.pet]; const a = v && v[kind] && (v[kind][S.lang] || v[kind].en); return Array.isArray(a) && a.length ? a : null; } catch (e) { return null; } }
/* 1) tifo: le frasi del compagno valgono doppio rispetto a quelle generiche */
Object.keys(T).forEach((l) => {
  const tk = T[l] && T[l].talk; if (!tk || !Array.isArray(tk.cheer)) return; const base = tk.cheer.slice();
  Object.defineProperty(tk, "cheer", { configurable: true, enumerable: true, get() { const own = S.lang === l ? v110Voice("cheer") : null; return own ? own.concat(own, base) : base; }, set(v) { if (Array.isArray(v)) { base.length = 0; base.push(...v); } } });
});
/* 2) promemoria: 3 frasi del compagno al posto delle frasi 3, 8 e 10 della rotazione (le 4, 6 e 7 restano: sono quelle di sola compagnia) */
function v110VoiceMsgs(msgs) { const own = v110Voice("notif"); if (!own || !Array.isArray(msgs) || msgs.length < 12) return msgs; const m = msgs.slice(); [3, 8, 10].forEach((i, k) => { if (own[k]) m[i] = own[k]; }); return m; }
/* 3) chat: quando il compagno non ha capito, una volta su due risponde con la sua voce (sempre di ascolto) */
const _chatReplyV110v = chatReply;
chatReply = function (raw) {
  const r = _chatReplyV110v.apply(this, arguments);
  try { if (r && !r.crisis && r.intent === "default" && Math.random() < 0.5) { const own = v110Voice("chat"); if (own) r.text = pick(own); } } catch (e) { /* niente */ }
  return r;
};
